package com.arjunren.coop;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.sql.*;import java.time.*;import java.util.*;
final class Database{final String url;Database(String u){url=u;}Connection connection()throws SQLException{return DriverManager.getConnection(url,System.getenv().getOrDefault("DB_USER","sa"),System.getenv().getOrDefault("DB_PASSWORD",""));}void migrate(){try(var in=getClass().getResourceAsStream("/db/migration.sql");var c=connection();var s=c.createStatement()){for(var q:new String(in.readAllBytes(),StandardCharsets.UTF_8).split(";"))if(!q.isBlank())s.execute(q);}catch(Exception e){throw new IllegalStateException(e);}}}
final class Passwords{String hash(String p){if(p.length()<12)throw new IllegalArgumentException();byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);return "210000:"+Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(key(p,salt));}boolean verify(String p,String h){try{var x=h.split(":");return MessageDigest.isEqual(Base64.getDecoder().decode(x[2]),key(p,Base64.getDecoder().decode(x[1])));}catch(Exception e){return false;}}byte[] key(String p,byte[]s){try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(p.toCharArray(),s,210000,256)).getEncoded();}catch(Exception e){throw new IllegalStateException(e);}}}
final class Auth{final Database db;final Passwords pw;Auth(Database d,Passwords p){db=d;pw=p;}Session login(String n,String p){try(var c=db.connection();var s=c.prepareStatement("SELECT id,password_hash,role,member_id FROM users WHERE username=?")){s.setString(1,n);try(var r=s.executeQuery()){if(!r.next()||!pw.verify(p,r.getString(2)))throw new SecurityException();var token=UUID.randomUUID()+""+UUID.randomUUID();try(var i=c.prepareStatement("INSERT INTO sessions VALUES(?,?,?)")){i.setString(1,digest(token));i.setLong(2,r.getLong(1));i.setObject(3,OffsetDateTime.now().plusHours(2));i.executeUpdate();}return new Session(token,r.getLong(1),r.getString(3),(Long)r.getObject(4));}}catch(SQLException e){throw new IllegalStateException(e);}}Principal require(String h,String...roles){if(h==null||!h.startsWith("Bearer "))throw new SecurityException();try(var c=db.connection();var s=c.prepareStatement("SELECT u.id,u.role,u.member_id FROM sessions s JOIN users u ON u.id=s.user_id WHERE token_hash=? AND expires_at>CURRENT_TIMESTAMP")){s.setString(1,digest(h.substring(7)));try(var r=s.executeQuery()){if(!r.next())throw new SecurityException();var p=new Principal(r.getLong(1),r.getString(2),(Long)r.getObject(3));if(roles.length>0&&Arrays.stream(roles).noneMatch(p.role::equals))throw new SecurityException();return p;}}catch(SQLException e){throw new IllegalStateException(e);}}String digest(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}record Session(String token,long userId,String role,Long memberId){}record Principal(long userId,String role,Long memberId){}}
